import React, { useEffect, useState } from "react";
import axios from "axios";
// import "./Artists.css";

function Artists() {
  const [artists, setArtists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/artists") // Change to your backend route
      .then((res) => {
        setArtists(res.data);
        setLoading(false);
      })
      .catch((err) => {
        setError("Failed to fetch artists. Please check your backend.");
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div className="loading">Loading artist data...</div>;
  }

  if (error) {
    return <div className="error">{error}</div>;
  }

  return (
    <div className="artists-container">
      <h1>All Artists</h1>
      <div className="artists-list">
        {artists.map((artist) => (
          <div className="artist-card" key={artist._id}>
            <img
              src={artist.profilePicture || "https://via.placeholder.com/150"}
              alt={artist.name}
              className="artist-image"
            />
            <h3>{artist.name}</h3>
            <p><strong>Category:</strong> {artist.category}</p>
            <p><strong>Email:</strong> {artist.email}</p>
            <p><strong>Bio:</strong> {artist.bio}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Artists;
